"""worker models GENERATED by `make gen-client` (TK-001)."""

from enum import Enum

from pydantic import BaseModel, Field


class Health(BaseModel):
    status: str


class Accepted(BaseModel):
    scheduled: bool
    purge_at: str = Field(default=None, description="Batas waktu penghapusan terjadwal")


class Ack(BaseModel):
    ok: bool


class JobState(str, Enum):
    UPLOADING = "uploading"
    QUEUED = "queued"
    PROCESSING = "processing"
    COMPLETED = "completed"
    FAILED = "failed"
    EXPIRED = "expired"
    CANCELLED = "cancelled"
    DELETED = "deleted"


class ProcessingStage(str, Enum):
    PROBING = "probing"
    TRANSCRIBING = "transcribing"
    DIARIZING = "diarizing"
    MERGING = "merging"


class KodeGalat(str, Enum):
    INVALID_FILE = "INVALID_FILE"
    UNSUPPORTED_TYPE = "UNSUPPORTED_TYPE"
    TOO_LARGE = "TOO_LARGE"
    TOO_LONG = "TOO_LONG"
    NO_AUDIO_STREAM = "NO_AUDIO_STREAM"
    CORRUPT_MEDIA = "CORRUPT_MEDIA"
    QUOTA_EXCEEDED = "QUOTA_EXCEEDED"
    TOO_MANY_ACTIVE_JOBS = "TOO_MANY_ACTIVE_JOBS"
    CONSENT_REQUIRED = "CONSENT_REQUIRED"
    ALLOWLIST_REQUIRED = "ALLOWLIST_REQUIRED"
    WORKER_OFFLINE = "WORKER_OFFLINE"
    LEASE_LOST = "LEASE_LOST"
    GPU_OOM = "GPU_OOM"
    DIARIZATION_FAILED = "DIARIZATION_FAILED"
    FFMPEG_ERROR = "FFMPEG_ERROR"
    JOB_TIMEOUT = "JOB_TIMEOUT"
    JOB_EXPIRED = "JOB_EXPIRED"
    VERSION_CONFLICT = "VERSION_CONFLICT"
    AUDIO_GONE = "AUDIO_GONE"
    INTERNAL = "INTERNAL"


class ConsentGive(BaseModel):
    document_version: str
    age_confirmed: bool = Field(description="Deklarasi berusia ≥ 18 tahun (D-05)")


class Consent(BaseModel):
    document_version: str
    given_at: str
    withdrawn_at: (str | None) = None


class UploadInit(BaseModel):
    filename: str
    size_bytes: int = Field(description="Batas 200 MB (US-01)")
    content_type: str
    language: str
    diarization: bool = Field(default=None, description="US-08, dihitung 2x kuota")
    min_speakers: int = None
    max_speakers: int = None
    turnstile_token: str


class UploadSession(BaseModel):
    job_id: str
    upload_id: str
    part_size: int
    part_count: int


class PartSignRequest(BaseModel):
    part_number: int


class PartSignResponse(BaseModel):
    url: str
    expires_at: str


class UploadStatus(BaseModel):
    job_id: str
    state: JobState
    parts_done: list[int]
    parts_total: int


class CompletedPart(BaseModel):
    part_number: int
    etag: str


class Job(BaseModel):
    job_id: str
    state: JobState
    stage: (ProcessingStage | None) = None
    filename: str
    size_bytes: int
    duration_seconds: (float | None) = None
    language: str
    diarization: bool
    billed_minutes: float = None
    attempts: int = None
    error_code: (KodeGalat | None) = None
    created_at: str
    finished_at: (str | None) = None


class JobSummary(Job):
    pass


class JobList(BaseModel):
    jobs: list[JobSummary]
    next_cursor: (str | None) = None


class JobDetail(BaseModel):
    job: Job
    queue_position: (int | None) = None
    eta_seconds: (float | None) = None
    worker_active: bool


class Segment(BaseModel):
    index: int
    start: float = Field(description="Detik")
    end: float = Field(description="Detik")
    text: str
    confidence: float
    speaker_id: (str | None) = None
    edited: bool = None
    version: int = Field(description="Naik tiap suntingan (deteksi tabrakan)")


class Speaker(BaseModel):
    speaker_id: str
    label: str
    display_name: str


class Transcript(BaseModel):
    job_id: str
    segments: list[Segment]
    speakers: list[Speaker]


class SegmentPatch(BaseModel):
    text: str = None
    speaker_id: (str | None) = None
    version: int


class SpeakerRename(BaseModel):
    display_name: str


class AudioUrl(BaseModel):
    url: str
    expires_at: str


class ClaimResponse(BaseModel):
    job_id: str
    audio_url: str = Field(description="URL GET R2 bertanda tangan (TTL 15 menit)")
    audio_expires_at: str
    language: str
    diarization: bool
    min_speakers: (int | None) = None
    max_speakers: (int | None) = None
    lease_until: str


class Heartbeat(BaseModel):
    stage: ProcessingStage
    progress_percent: float = None


class HeartbeatResponse(BaseModel):
    cancel: bool = Field(description="True bila pengguna menghapus job — pekerja wajib berhenti dan hapus berkas kerja")
    lease_until: str


class WorkerResult(BaseModel):
    segments: list[Segment]
    speakers: list[Speaker] = Field(default=None, description="Kosong bila diarisasi mati atau gagal (AI-13)")
    diarization_available: bool = None
    duration_seconds: float
    xrt: float = Field(description="Kecepatan relatif (durasi audio / waktu proses)")
    model_version: str
    low_confidence_ratio: float


class WorkerFail(BaseModel):
    code: KodeGalat = Field(description="Daftar kode galat + pesan manusiawi ada di contracts/worker-protocol.md")
    retryable: bool
    detail: str = Field(default=None, description="Tanpa nama berkas / teks transkrip (AI-10)")


class WorkerPing(BaseModel):
    worker_id: str
    version: str


class WorkerPingResponse(BaseModel):
    ok: bool
    min_version: str
    update_required: bool


class Error(BaseModel):
    code: KodeGalat = Field(description="Daftar kode galat + pesan manusiawi ada di contracts/worker-protocol.md")
    message: str = Field(description="Pesan manusiawi Bahasa Indonesia")


class Me(BaseModel):
    user_id: str
    email: str
    quota_minutes_remaining: float
    active_jobs: int
    consent: (Consent | None)


class UploadComplete(BaseModel):
    parts: list[CompletedPart]

